import math


def forwards_package_data(apps, schema_editor):
    """
    - Optional items used to have no effect on price, so packages without any
      required item get all their items marked required.
    - Installments move from "amount per payment" to "number of payments".
    """
    ServicePackages = apps.get_model("services", "ServicePackages")

    for package in ServicePackages.objects.prefetch_related("items"):
        items = list(package.items.all())
        if items and not any(item.required for item in items):
            package.items.update(required=True)
            for item in items:
                item.required = True

        if package.installment_amount is None:
            continue

        subtotal = sum(
            (item.price * item.quantity for item in items if item.required),
            Decimal("0.00"),
        )
        if package.pricing_method == "fixed_price":
            total = package.fixed_price or Decimal("0.00")
        elif package.pricing_method == "percentage_discount":
            total = subtotal * (
                1 - (package.percentage_discount or Decimal("0.00")) / 100
            )
        elif package.pricing_method == "fixed_discount":
            total = subtotal - (package.fixed_discount or Decimal("0.00"))
        else:
            total = subtotal

        count = math.ceil(max(total, Decimal("0.00")) / package.installment_amount)
        package.installment_count = min(max(count, 2), 52)
        package.save(update_fields=["installment_count"])


